-- Initial file generated by Claude Sonnet 5.5

module Zocalo.Common.SecureTokenSpec(tests) where

import Data.Text.Encoding(decodeUtf8)

import Test.Framework(Test, testGroup)
import Test.Framework.Providers.HUnit(testCase)
import Test.HUnit(assertBool, (@?=))

import qualified Data.ByteString            as BS
import qualified Data.ByteString.Base64.URL as B64
import qualified Data.Text                  as Text

import Zocalo.Common.SecureToken(
    genSecureToken, hashToken, SecureToken(SecureToken, tokenText), tokenFromText
  )

tests :: Test
tests =
  testGroup "Zocalo.Common.SecureToken" $
    [ testCase "a freshly generated token is accepted by tokenFromText, unchanged" $ do
        token <- genSecureToken
        tokenFromText (tokenText token) @?= Just token

    , testCase "two generated tokens differ" $ do
        a <- genSecureToken
        b <- genSecureToken
        assertBool "tokens should be unique" (a /= b)

    , testCase "tokenFromText accepts base64url text that decodes to exactly 32 bytes" $
        tokenFromText thirtyTwoBytes @?= Just (SecureToken thirtyTwoBytes)

    , testCase "tokenFromText rejects valid base64url that decodes to the wrong length" $
        tokenFromText sixteenBytes @?= Nothing

    , testCase "tokenFromText rejects the empty string" $
        tokenFromText "" @?= Nothing

    , testCase "tokenFromText rejects text that is not base64url" $
        tokenFromText "!!!!" @?= Nothing

    , testCase "hashToken is SHA-256 (hex) of the token text: FIPS 180-2 test vector for \"abc\"" $
        hashToken (SecureToken "abc") @?= "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"

    , testCase "hashToken yields 64 lowercase hex characters and never echoes the token" $ do
        token <- genSecureToken
        let hashed = hashToken token
        Text.length hashed @?= 64
        assertBool "should be lowercase hex" (Text.all (`Text.elem` "0123456789abcdef") hashed)
        assertBool "hash must differ from the raw token" (hashed /= tokenText token)

    , testCase "hashToken is deterministic" $ do
        token <- genSecureToken
        hashToken token @?= hashToken token
    ]

  where
    thirtyTwoBytes = decodeUtf8 $ B64.encode $ BS.replicate 32 7
    sixteenBytes   = decodeUtf8 $ B64.encode $ BS.replicate 16 7
